SELECT customer_id,COUNT(*) total_orders,ROUND(100*SUM((TIME(order_timestamp) BETWEEN '11:00:00' AND '14:00:00') OR (TIME(order_timestamp) BETWEEN '18:00:00' AND '21:00:00'))/COUNT(*),0) peak_hour_percentage,ROUND(AVG(order_rating),2) average_rating FROM restaurant_orders GROUP BY customer_id HAVING COUNT(*)>=3 AND SUM((TIME(order_timestamp) BETWEEN '11:00:00' AND '14:00:00') OR (TIME(order_timestamp) BETWEEN '18:00:00' AND '21:00:00'))/COUNT(*)>=0.6 AND AVG(order_rating)>=4 AND COUNT(order_rating)/COUNT(*)>=0.5 ORDER BY average_rating DESC,customer_id DESC;